import{_ as a,o as n,c as r,a5 as s}from"./chunks/framework.a5no_H3L.js";const h=JSON.parse('{"title":"PEB、TEB 与模块加载","description":"程序运行时会加载多个模块，系统为每个进程和每个线程维护管理结构。这一章讲三个东西：模块基址、PEB（进程环境块）、TEB（线程环境块），以及它们如何串起「从 GS 到函数地址」这条链。","frontmatter":{"type":"explanation","level":"intermediate"},"headers":[],"relativePath":"reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md","filePath":"reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md"}'),i={name:"reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md"};function t(d,e,l,o,c,p){return n(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="peb、teb-与模块加载" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">PEB、TEB 与模块加载 <a class="header-anchor" href="#peb、teb-与模块加载" aria-label="Permalink to &quot;PEB、TEB 与模块加载&quot;">​</a></h1><p data-src-line="4" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">程序运行时会加载多个模块，系统为每个进程和每个线程维护管理结构。这一章讲三个东西：模块基址、PEB（进程环境块）、TEB（线程环境块），以及它们如何串起「从 GS 到函数地址」这条链。</p><h2 id="_1-模块与模块基址" tabindex="-1" data-src-line="6" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">1. 模块与模块基址 <a class="header-anchor" href="#_1-模块与模块基址" aria-label="Permalink to &quot;1. 模块与模块基址&quot;">​</a></h2><p data-src-line="8" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">程序运行时会加载多个<strong>模块（module）</strong>：主程序自己的 <code>.exe</code>，以及它依赖的 <code>.dll</code>（<code>ntdll.dll</code>、<code>kernel32.dll</code> 等）。每个模块加载后，在进程地址空间里占据一段连续的内存，这段内存的起始地址叫<strong>模块基址（module base）</strong>。</p><p data-src-line="10" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">PE 的 <code>ImageBase</code> 字段是模块「首选」加载地址（x64 默认 <code>0x140000000</code>），但首选地址不是保证值，两个因素会让实际基址变化：</p><ul data-src-line="12" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md"><li data-src-line="12" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md"><strong>地址冲突</strong>：多个 DLL 首选地址重叠，后面的只能挪到别处。</li><li data-src-line="13" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md"><strong>ASLR</strong>：系统故意给模块基址加随机偏移。</li></ul><p data-src-line="15" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">因此，你不能假设模块每次都加载在 <code>ImageBase</code>。正确的做法是记住一个「偏移」：<code>函数实际地址 = 模块基址 + RVA</code>。反汇编器默认按 <code>ImageBase</code> 显示地址，调试器则显示真实地址，两者相差一个「基址偏移量」。</p><h2 id="_2-peb-与-teb" tabindex="-1" data-src-line="17" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">2. PEB 与 TEB <a class="header-anchor" href="#_2-peb-与-teb" aria-label="Permalink to &quot;2. PEB 与 TEB&quot;">​</a></h2><p data-src-line="19" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">系统为每个线程和每个进程维护了管理结构，逆向里最常遇到两个：<strong>TEB</strong> 和 <strong>PEB</strong>。</p><p data-src-line="21" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md"><strong>TEB（Thread Environment Block，线程环境块）</strong>：每个线程一个，记录该线程的栈范围、异常处理链、TLS 等。在 x64 上通过 <code>GS</code> 段寄存器访问（x86 是 <code>FS</code>）。你在反汇编里看到 <code>mov rax, gs:[30h]</code> 这种指令，就是在读 TEB。</p><p data-src-line="23" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md"><strong>PEB（Process Environment Block，进程环境块）</strong>：每个进程一个，记录进程级信息。它在 TEB 的一个固定偏移处（<code>TEB.ProcessEnvironmentBlock</code>，偏移 <code>0x60</code>）。所以常见的套路是：</p><div class="language-asm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">asm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">mov</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> rax</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">gs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60h</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">; 从 TEB 取 PEB 地址</span></span></code></pre></div><p data-src-line="29" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">PEB 里对逆向最有用的，是<strong>已加载模块链表</strong>：<code>PEB.Ldr</code> 指向 <code>PEB_LDR_DATA</code>，里面维护着进程已加载的所有模块（基址、名称等）。</p><h2 id="_3-gs-→-peb-→-模块链表-→-函数地址" tabindex="-1" data-src-line="31" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">3. GS → PEB → 模块链表 → 函数地址 <a class="header-anchor" href="#_3-gs-→-peb-→-模块链表-→-函数地址" aria-label="Permalink to &quot;3. GS → PEB → 模块链表 → 函数地址&quot;">​</a></h2><p data-src-line="33" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">把上面几个概念串成一条链，就是逆向里反复出现的手法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GS 段寄存器</span></span>
<span class="line"><span>  → TEB（线程环境块）</span></span>
<span class="line"><span>    → PEB（进程环境块，偏移 0x60）</span></span>
<span class="line"><span>      → PEB.Ldr（PEB_LDR_DATA）</span></span>
<span class="line"><span>        → 模块链表（记录各模块基址）</span></span>
<span class="line"><span>          → 找到 kernel32.dll 基址</span></span>
<span class="line"><span>            → 再找 GetProcAddress → 动态解析任意函数</span></span></code></pre></div><p data-src-line="45" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">这一套「通过 PEB 找模块基址、再找函数地址」的手法，常被恶意软件和加壳程序用来<strong>不依赖导入表</strong>地动态获取函数。因为导入表会暴露「程序用了哪些函数」，而这种方式把函数名藏起来了，静态分析看不到。</p><p data-src-line="47" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">你现在只需知道 PEB/TEB 是什么、为什么反汇编里会出现 <code>gs:[60h]</code>；具体利用方式在<a href="./../07-packing/chapter-03-virtualization-anti-debugging.html">反调试与反静态分析</a>和<a href="./../07-packing/chapter-01-packing-principle.html">加壳与脱壳</a>里会用到。</p><h2 id="_4-loader-谁在加载模块" tabindex="-1" data-src-line="49" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">4. Loader：谁在加载模块 <a class="header-anchor" href="#_4-loader-谁在加载模块" aria-label="Permalink to &quot;4. Loader：谁在加载模块&quot;">​</a></h2><p data-src-line="51" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">前面 PE 加载过程讲过，Windows 的<strong>加载器（Loader）</strong> 负责把 PE 文件映射进内存、解析导入表、加载依赖 DLL。这套机制在 <code>ntdll.dll</code> 里实现（如 <code>LdrLoadDll</code>、<code>LdrpLoadImportModule</code> 等内部函数）。</p><p data-src-line="53" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">理解 Loader 的存在，能解释几个现象：</p><ul data-src-line="55" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md"><li data-src-line="55" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">导入函数的地址是加载时确定的，不是编译时。</li><li data-src-line="56" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">模块链表、PEB 这些结构是 Loader 维护的。</li><li data-src-line="57" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">加壳程序往往自己实现一部分「加载」逻辑（还原节区、手工解析导入），绕开标准 Loader，这正是<a href="./../07-packing/chapter-01-packing-principle.html">加壳与脱壳</a>要面对的问题。</li></ul><hr><blockquote data-src-line="61" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md"><p data-src-line="61" data-src-file="reverse-engineering/03-windows-internals/chapter-04-peb-teb-loader.md">本章建立的是模块加载的管理视图：模块基址受 ASLR 影响而每次变化，PEB/TEB 是定位模块与线程信息的关键结构，GS→PEB→模块链表是动态解析函数的常见路径。下一章看程序如何应对运行时错误——<a href="./chapter-05-exception-handling.html">异常处理机制</a>。</p></blockquote>`,24)])])}const b=a(i,[["render",t]]);export{h as __pageData,b as default};
